package com.autocare.platform.order;
import com.autocare.platform.gateway.identity.*;
import com.autocare.platform.vehicle.VehicleOwner;
import com.autocare.platform.common.write.WriteIntegrityService.*;
import com.fasterxml.jackson.databind.JsonNode;
import java.util.*;
import static com.autocare.platform.order.ReservationStore.*;

/** Owner-submitted text and explicit operator assignment; no implicit archive access. */
public class CommunityQuestions {
 final ReservationStore db;final CommunityQuestionPolicies service;final PointLedger identity;
 public CommunityQuestions(ReservationStore db,CommunityQuestionPolicies service){this(db,service,null);}
 public CommunityQuestions(ReservationStore db,CommunityQuestionPolicies service,PointLedger identity){this.db=db;this.service=service;this.identity=identity;}
 static JsonNode input(String raw,String action){var b=CouponInput.parse(raw);switch(action){
  case "create"->{CouponInput.exact(b,"vehicle_id","policy_id","policy_revision","category","message","consent");CouponInput.id(b.get("vehicle_id"));if(!Set.of("MAINTENANCE","REPAIR","FAULT").contains(b.path("category").asText()))throw ReservationInput.bad();admissionInput(b);}
  case "message"->{CouponInput.exact(b,"expected_revision","policy_id","policy_revision","message","consent");CouponInput.version(b.get("expected_revision"));admissionInput(b);}
  case "reply"->{CouponInput.exact(b,"expected_revision","message");CouponInput.version(b.get("expected_revision"));messageText(b.get("message"));}
  case "assign"->{CouponInput.exact(b,"expected_revision","operator_id");CouponInput.version(b.get("expected_revision"));CouponInput.id(b.get("operator_id"));}
  case "close"->{CouponInput.exact(b,"expected_revision");CouponInput.version(b.get("expected_revision"));}
  default->throw ReservationInput.bad();}return b;
 }
 static String messageText(JsonNode n){if(n==null||!n.isTextual())throw ReservationInput.bad();String value=n.textValue();DiagnosisServicePolicies.text(com.fasterxml.jackson.databind.node.TextNode.valueOf(value.replace("\n"," ")),1,2000);return value;}
 private static void admissionInput(JsonNode b){CouponInput.id(b.get("policy_id"));CouponInput.id(b.get("policy_revision"));messageText(b.get("message"));if(!b.path("consent").isBoolean()||!b.path("consent").asBoolean())throw ReservationInput.bad();}
 Map<String,Object> row(long id,boolean lock){return db.one("SELECT * FROM community_qa_case WHERE id=?"+(lock?" FOR UPDATE":""),id);}
 private Map<String,Object> owner(VehicleOwner a,long id,boolean lock){db.owner(a,lock);return db.one("SELECT * FROM community_qa_case WHERE id=? AND owner_id=?"+(lock?" FOR UPDATE":""),id,a.id());}
 private void handler(OperatorActor a,Map<String,Object> c,boolean lock){service.operators.authorize(a,OperatorIdentity.Permission.COMMUNITY_ANSWER,lock);if(c.get("assigned_operator_id")==null||number(c,"assigned_operator_id")!=a.id())throw missing();}
 private void scope(Object a,long id,boolean lock,boolean closing){if(a instanceof VehicleOwner u){owner(u,id,lock);return;}var op=(OperatorActor)a;service.operators.authorize(op,OperatorIdentity.Permission.COMMUNITY_ANSWER,lock);handler(op,row(id,lock),false);}
 private Map<String,Object> basicVehicle(long owner,long vehicle,boolean lock){
  db.one("SELECT id FROM vehicle WHERE id=? AND user_id=? AND is_deleted=0"+(lock?" FOR UPDATE":""),vehicle,owner);
  var rows=db.jdbc.queryForList("SELECT m.id AS model_id,b.name AS brand,s.name AS series,m.year,m.config_name FROM vehicle v JOIN model m ON m.id=v.model_id AND m.status=1 AND m.is_deleted=0 JOIN series s ON s.id=m.series_id AND s.status=1 AND s.is_deleted=0 JOIN brand b ON b.id=s.brand_id AND b.status=1 AND b.is_deleted=0 WHERE v.id=?"+(lock?" FOR UPDATE":""),vehicle);
  if(rows.size()!=1)throw CommunityQuestionPolicies.conflict();return rows.get(0);
 }
 private Map<String,Object> admit(VehicleOwner a,long vehicle,JsonNode b){
  // All business writers already hold the control row; lock current handlers before admission.
  db.jdbc.queryForList("SELECT id FROM operator_account WHERE status='ACTIVE' AND can_community_answer=1 ORDER BY id FOR UPDATE");
  basicVehicle(a.id(),vehicle,true);var available=service.availability(true);var policy=(Map<?,?>)available.get("policy");
  if(!Boolean.TRUE.equals(available.get("accepting"))||policy==null||((Number)policy.get("id")).longValue()!=b.path("policy_id").asLong()||((Number)policy.get("revision")).longValue()!=b.path("policy_revision").asLong())throw CommunityQuestionPolicies.conflict();
  boolean verified=identity!=null&&identity.verifiedIdentity(a,true);String app=verified?db.jdbc.queryForObject("SELECT app_id FROM auth_session WHERE id=?",String.class,a.session()):"";return Map.of("service",policy,"checked_at",db.now().toString(),"rule_version","R8C_PRIVATE_QA_V1","identity_source",verified?"VERIFIED_WECHAT":"UNKNOWN","identity_app_id",app);
 }
 public Map<String,Object> context(VehicleOwner a){return service.current(a);}
 private String hash(JsonNode b){var sorted=new TreeMap<String,Object>();b.fields().forEachRemaining(e->sorted.put(e.getKey(),e.getValue()));return AuthTokens.sha256(db.json(sorted));}
 private Map<String,Object> summary(Map<String,Object> c,boolean manage){var out=new LinkedHashMap<String,Object>();out.put("case_id",c.get("id"));for(String k:List.of("revision","status"))out.put(k,c.get(k));for(String k:List.of("created_at","updated_at"))out.put(k,iso(c.get(k)));if(manage)out.put("assigned_operator_id",c.get("assigned_operator_id"));return out;}
 private Map<String,Object> receipt(long id,long revision,String status){return Map.of("case_id",id,"revision",revision,"status",status);}
 private void event(long id,long revision,String kind){db.jdbc.update("INSERT INTO community_qa_case_event(case_id,case_revision,kind,occurred_at) VALUES(?,?,?,?)",id,revision,kind,time(db.now()));}
 private void message(long id,long revision,String sender,long senderId,String body,Object proof){String hash=CommunityQuestionSource.messageHash(db,row(id,true),revision,sender,senderId,body,proof);db.jdbc.update("INSERT INTO community_qa_message(case_id,case_revision,sender_type,sender_id,body,admission_snapshot,created_at,source_hash) VALUES(?,?,?,?,?,?,?,?)",id,revision,sender,senderId,body,proof==null?null:db.json(proof),time(db.now()),hash);}
 private Map<String,Object> auditAfter(Map<String,Object> receipt,long id,long revision){var out=new LinkedHashMap<String,Object>(receipt);var rows=db.jdbc.queryForList("SELECT source_hash FROM community_qa_message WHERE case_id=? AND case_revision=?",id,revision);if(!rows.isEmpty())out.put("message_hash",rows.get(0).get("source_hash"));return out;}
 public JsonNode create(VehicleOwner a,String key,JsonNode b){String canonical=com.autocare.platform.common.write.WriteIntegrityService.normalizeKey(key),hash=hash(b);return db.writes.execute(new Actor("user",a.id()),"POST","/api/owner/community/questions/cases",key,b,()->{db.owner(a,false);service.guard();db.owner(a,true);},()->{
  var old=db.jdbc.queryForList("SELECT id,submission_hash,creation_result FROM community_qa_case WHERE owner_id=? AND submission_key=?",a.id(),canonical);if(!old.isEmpty()){if(!hash.equals(old.get(0).get("submission_hash")))throw ReservationInput.bad();long id=number(old.get(0),"id");var r=db.mapper.convertValue(db.parse(old.get(0).get("creation_result")),new com.fasterxml.jackson.core.type.TypeReference<Map<String,Object>>(){});return new Change("COMMUNITY_QUESTION_CREATE","community_qa_case",id,r,r,r,false);}
  long vehicle=b.path("vehicle_id").asLong();var proof=admit(a,vehicle,b);long id=db.insert("INSERT INTO community_qa_case(owner_id,vehicle_id,vehicle_snapshot,submission_key,submission_hash,admission_snapshot,category,created_at,updated_at) VALUES(?,?,?,?,?,?,?,?,?)",a.id(),vehicle,db.json(basicVehicle(a.id(),vehicle,false)),canonical,hash,db.json(proof),b.path("category").asText(),time(db.now()),time(db.now()));message(id,1,"OWNER",a.id(),b.path("message").asText(),proof);event(id,1,"CREATED");var r=receipt(id,1,"WAITING");db.jdbc.update("UPDATE community_qa_case SET creation_result=? WHERE id=?",db.json(r),id);return new Change("COMMUNITY_QUESTION_CREATE","community_qa_case",id,Map.of(),auditAfter(r,id,1),r);
 });}
 public Map<String,Object> list(Object a,boolean queue,int page){return db.reads.execute(tx->{String where;Object id;if(a instanceof VehicleOwner u){db.owner(u,false);where="owner_id=?";id=u.id();}else{var op=(OperatorActor)a;service.operators.authorize(op,queue?OperatorIdentity.Permission.COMMUNITY_MANAGE:OperatorIdentity.Permission.COMMUNITY_ANSWER,false);where=queue?"1=?":"assigned_operator_id=?";id=queue?1:op.id();}long total=db.jdbc.queryForObject("SELECT COUNT(*) FROM community_qa_case WHERE "+where,Long.class,id);return page(db.jdbc.queryForList("SELECT id,revision,status,created_at,updated_at,assigned_operator_id FROM community_qa_case WHERE "+where+" ORDER BY id DESC LIMIT 20 OFFSET ?",id,(page-1)*20L).stream().map(c->summary(c,queue)).toList(),total,page,20);});}
 public Map<String,Object> detail(Object a,long id,int page){return db.reads.execute(tx->{scope(a,id,false,false);var c=row(id,false);long total=db.jdbc.queryForObject("SELECT COUNT(*) FROM community_qa_message WHERE case_id=?",Long.class,id);var rows=db.jdbc.queryForList("SELECT id,sender_type,body,created_at FROM community_qa_message WHERE case_id=? ORDER BY id LIMIT 20 OFFSET ?",id,(page-1)*20L);var items=new ArrayList<Map<String,Object>>();for(var r:rows)items.add(Map.of("message_id",r.get("id"),"sender",r.get("sender_type"),"body",r.get("body"),"created_at",iso(r.get("created_at"))));return Map.of("case",summary(c,false),"vehicle",db.parse(c.get("vehicle_snapshot")),"category",c.get("category"),"messages",page(items,total,page,20));});}
 public JsonNode assign(OperatorActor a,long id,String key,JsonNode b){long target=b.path("operator_id").asLong();return db.writes.execute(new Actor("operator_account",a.id()),"PUT","/api/admin/community/questions/cases/"+id+"/assignment",key,b,()->{service.manage(a,false);service.guard();db.jdbc.queryForList("SELECT id FROM operator_account WHERE id IN (?,?) ORDER BY id FOR UPDATE",a.id(),target);service.manage(a,true);db.one("SELECT id FROM operator_account WHERE id=? AND status='ACTIVE' AND can_community_answer=1 FOR UPDATE",target);row(id,true);},()->{var c=row(id,true);check(c,b);var before=summary(c,true);long rev=number(c,"revision")+1;db.jdbc.update("UPDATE community_qa_case SET assigned_operator_id=?,status='PROCESSING',revision=?,updated_at=? WHERE id=?",target,rev,time(db.now()),id);event(id,rev,"ASSIGNED");var after=receipt(id,rev,"PROCESSING");return new Change("COMMUNITY_QUESTION_ASSIGN","community_qa_case",id,before,after,after);});}
 private void check(Map<String,Object> c,JsonNode b){if("CLOSED".equals(c.get("status"))||number(c,"revision")!=b.path("expected_revision").asLong())throw CommunityQuestionPolicies.conflict();}
 public JsonNode write(Object a,long id,String action,String key,JsonNode b){boolean own=a instanceof VehicleOwner;var actor=own?new Actor("user",((VehicleOwner)a).id()):new Actor("operator_account",((OperatorActor)a).id());return db.writes.execute(actor,"POST","/api/"+(own?"owner":"admin")+"/community/questions/cases/"+id+"/"+action,key,b,()->{scope(a,id,false,action.equals("close"));service.guard();scope(a,id,true,action.equals("close"));},()->{
  var c=row(id,true);check(c,b);var before=summary(c,false);long rev=number(c,"revision")+1;String status,kind;
  if(action.equals("close")){status="CLOSED";kind="CLOSED";}else if(own){var proof=admit((VehicleOwner)a,number(c,"vehicle_id"),b);boolean valid=c.get("assigned_operator_id")!=null&&!db.jdbc.queryForList("SELECT id FROM operator_account WHERE id=? AND status='ACTIVE' AND can_community_answer=1 FOR UPDATE",c.get("assigned_operator_id")).isEmpty();status=valid?"PROCESSING":"WAITING";if(!valid)db.jdbc.update("UPDATE community_qa_case SET assigned_operator_id=NULL WHERE id=?",id);message(id,rev,"OWNER",actor.id(),b.path("message").asText(),proof);kind="MESSAGE";}else{if(!"PROCESSING".equals(c.get("status")))throw CommunityQuestionPolicies.conflict();status="REPLIED";kind="REPLIED";message(id,rev,"OPERATOR",actor.id(),b.path("message").asText(),null);}
  db.jdbc.update("UPDATE community_qa_case SET revision=?,status=?,updated_at=?,closed_at=? WHERE id=?",rev,status,time(db.now()),status.equals("CLOSED")?time(db.now()):null,id);event(id,rev,kind);var after=receipt(id,rev,status);return new Change("COMMUNITY_QUESTION_"+kind,"community_qa_case",id,before,auditAfter(after,id,rev),after);
 });}
}
